from google.cloud import texttospeech


def synthesize_ssml(payload, config=None):
    config = config or {}
    client = texttospeech.TextToSpeechClient()
    response = client.synthesize_speech(
        input=texttospeech.SynthesisInput(ssml=payload["ssml"]),
        voice=texttospeech.VoiceSelectionParams(
            language_code=config.get("language_code", "en-US"),
            name=config.get("voice_name", None),
            ssml_gender=texttospeech.SsmlVoiceGender[config.get("ssml_gender", "NEUTRAL")]
        ),
        audio_config=texttospeech.AudioConfig(
            audio_encoding=texttospeech.AudioEncoding.MP3,
            speaking_rate=config.get("speaking_rate", 1.0),
            pitch=config.get("pitch", 0.0)
        )
    )
    return {"audio_bytes": response.audio_content, "content_type": "audio/mpeg"}

from google.cloud import texttospeech


def get_tts_client():
    """Provides a configured Google Cloud Text-to-Speech client."""
    return texttospeech.TextToSpeechClient()


def get_translation_client():
    from google.cloud import translate_v2 as translate
    """Provides a configured Google Cloud Translation client."""
    return translate.Client()


def get_vertex_ai_prediction_client(project, location):
    from google.cloud import aiplatform
    """Provides a configured Google Cloud Vertex AI Prediction client."""
    aiplatform.init(project=project, location=location)
    return aiplatform.gapic.PredictionServiceClient()


def get_speech_to_text_client():
    from google.cloud import speech_v1p1beta1 as speech
    """Provides a configured Google Cloud Speech-to-Text client."""
    return speech.SpeechClient()

class SynthesisInput:
    def __init__(self, text=None, ssml=None):
        if text is not None and ssml is not None:
            raise ValueError("Provide either text or ssml, not both.")
        self.text = text
        self.ssml = ssml


class VoiceConfig:
    def __init__(self, language_code="en-US", name=None, ssml_gender="NEUTRAL"):
        self.language_code = language_code
        self.name = name
        self.ssml_gender = ssml_gender


class AudioConfig:
    def __init__(self,
        audio_encoding="MP3",
        speaking_rate=1.0,
        pitch=0.0,
        volume_gain_db=0.0,
        sample_rate_hertz=None,
    ):
        self.audio_encoding = audio_encoding
        self.speaking_rate = speaking_rate
        self.pitch = pitch
        self.volume_gain_db = volume_gain_db
        self.sample_rate_hertz = sample_rate_hertz


class SynthesisResponse:
    def __init__(self, audio_content, content_type="audio/mpeg"):
        self.audio_content = audio_content
        self.content_type = content_type


class VoiceSelectionResponse:
    def __init__(self,
        name,
        language_codes,
        ssml_gender,
        natural_sample_rate_hertz,
    ):
        self.name = name
        self.language_codes = language_codes
        self.ssml_gender = ssml_gender
        self.natural_sample_rate_hertz = natural_sample_rate_hertz

from speech_client import get_translation_client


def script_translate(text, target_language="es", source_language=None):
    client = get_translation_client()

    # Text can also be a list of strings
    result = client.translate(text, target_language=target_language, source_language=source_language)

    if isinstance(text, list):
        return [translation["translatedText"] for translation in result]
    else:
        return result["translatedText"]
